import{_ as e,a as r,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"图论与路径","description":"先区分可达性、依赖约束、最短路、最小生成树和容量流，再按有向性、边权与图规模选择算法。","frontmatter":{"title":"图论与路径","description":"先区分可达性、依赖约束、最短路、最小生成树和容量流，再按有向性、边权与图规模选择算法。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"先区分可达性、依赖约束、最短路、最小生成树和容量流，再按有向性、边权与图规模选择算法。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"拓扑排序","link":"/principles/algorithms/graphs/topological-sort"},"next":{"text":"有向图环检测","link":"/principles/algorithms/graphs/cycle-detection"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"拓扑排序","link":"/principles/algorithms/graphs/topological-sort"},"next":{"text":"有向图环检测","link":"/principles/algorithms/graphs/cycle-detection"}},"headers":[],"relativePath":"principles/algorithms/graphs/algorithms-graphs-general-general.md","filePath":"principles/algorithms/graphs/algorithms-graphs-general-general.md"}'),i={name:"principles/algorithms/graphs/algorithms-graphs-general-general.md"};function s(p,a,l,d,o,c){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="图论与路径" tabindex="-1">图论与路径 <a class="header-anchor" href="#图论与路径" aria-label="Permalink to &quot;图论与路径&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>约定顶点编号为 0 到 V-1，所有邻接下标和起点均须合法；矩阵表示要求方形。每个 package main 是独立文件/模块（Go 1.22+），不能合并重复 Edge。距离、路径费用与容量计算均要求中间结果可用 int 表示，inf 不能与合法距离混淆；本轮输出仅经静态推导，未执行。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>遍历可达节点或划分无向图连通分量</td><td><a href="#entry-graph-dfs-1cc4d97cac">DFS</a>、<a href="#entry-graph-bfs-6293bfc13e">BFS</a>、<a href="#entry-connected-components-9e156afdb6">连通分量</a></td><td>BFS 的首次到达只在无权图表示最短步数；深图递归需关注栈深度。</td></tr><tr><td>安排依赖顺序、检测有向环或分成两组</td><td><a href="#entry-topological-sort-86a49bb696">拓扑排序</a>、<a href="#entry-cycle-detection-908d1d9810">三色 DFS</a>、<a href="#entry-bipartite-graph-7ded796464">二分图判定</a></td><td>拓扑排序仅对 DAG 输出全部节点；二分图染色与依赖排序解决不同约束。</td></tr><tr><td>从一个起点求非负边权最短路</td><td><a href="#entry-dijkstra-9ff28567bb">Dijkstra</a></td><td>示例扫描实现为 O(V²+E)；大型稀疏图可用堆降低选点成本。</td></tr><tr><td>路径可能含负边</td><td><a href="#entry-bellman-ford-20dc270551">Bellman–Ford</a></td><td>时间 O(VE)，可检测从起点可达的负权环。</td></tr><tr><td>小图需要频繁查询所有点对距离</td><td><a href="#entry-floyd-warshall-3733afc1b1">Floyd–Warshall</a></td><td>时间 O(V³)；不可达值与距离相加须避免溢出。</td></tr><tr><td>以最低总成本连接顶点</td><td><a href="#entry-kruskal-24e59e257d">Kruskal</a>或<a href="#entry-prim-b7857a9f45">Prim</a></td><td>Kruskal 排序边并用并查集判环；Prim 示例用矩阵，时间 O(V²)，图不连通时无单棵生成树。</td></tr><tr><td>边有容量限制，需要最大总传输量</td><td><a href="#entry-max-flow-2108859bd0">最大流与残量网络</a></td><td>Edmonds–Karp 示例用 BFS 寻找增广路，并会修改传入容量矩阵。</td></tr></tbody></table><h2 id="scene-reach-and-connect" tabindex="-1">遍历可达节点与划分连通分量 <a class="header-anchor" href="#scene-reach-and-connect" aria-label="Permalink to &quot;遍历可达节点与划分连通分量 {#scene-reach-and-connect}&quot;">​</a></h2><h3 id="entry-graph-bfs-6293bfc13e" tabindex="-1">广度优先搜索 <a class="header-anchor" href="#entry-graph-bfs-6293bfc13e" aria-label="Permalink to &quot;广度优先搜索 {#entry-graph-bfs-6293bfc13e}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-graph-bfs-6293bfc13e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/graph-bfs">广度优先搜索</a>。</p><p>边有不同权重时首次到达不一定最优，应使用合适的带权最短路算法。</p><h3 id="entry-graph-dfs-1cc4d97cac" tabindex="-1">深度优先搜索 <a class="header-anchor" href="#entry-graph-dfs-1cc4d97cac" aria-label="Permalink to &quot;深度优先搜索 {#entry-graph-dfs-1cc4d97cac}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-graph-dfs-1cc4d97cac-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/graph-dfs">深度优先搜索</a>。</p><p>从起点递归访问尚未见过的邻居，seen 防止在环中重复进入节点。它能用于可达性、连通分量和回溯搜索。 遍历时间 O(V+E)。</p><p>每个顶点和边至多处理常数次；极深图可改用显式栈避免递归栈过深。</p><h3 id="entry-connected-components-9e156afdb6" tabindex="-1">连通分量 <a class="header-anchor" href="#entry-connected-components-9e156afdb6" aria-label="Permalink to &quot;连通分量 {#entry-connected-components-9e156afdb6}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-connected-components-9e156afdb6-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/connected-components">连通分量</a>。</p><p>在无向图里，从一个未访问节点出发能到达的所有节点构成一个连通分量。对每个剩余起点重复搜索即可得到完整划分。 总时间 O(V+E)。</p><p>示例用栈迭代并在入栈时标记，避免同一节点被多次加入。</p><h2 id="scene-validate-constraints" tabindex="-1">检查依赖顺序、环与二分分组约束 <a class="header-anchor" href="#scene-validate-constraints" aria-label="Permalink to &quot;检查依赖顺序、环与二分分组约束 {#scene-validate-constraints}&quot;">​</a></h2><h3 id="entry-topological-sort-86a49bb696" tabindex="-1">拓扑排序 <a class="header-anchor" href="#entry-topological-sort-86a49bb696" aria-label="Permalink to &quot;拓扑排序 {#entry-topological-sort-86a49bb696}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-topological-sort-86a49bb696-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/topological-sort">拓扑排序</a>。</p><p>先统计每个节点的入度，把所有入度为零的节点放入队列。移除节点时减少其后继的入度，新变成零的节点即可入队。 仅有向无环图能输出全部节点。</p><p>若结果数量小于顶点数，剩余节点属于有向环或依赖于环，无法给出完整顺序。</p><h3 id="entry-cycle-detection-908d1d9810" tabindex="-1">有向图环检测 <a class="header-anchor" href="#entry-cycle-detection-908d1d9810" aria-label="Permalink to &quot;有向图环检测 {#entry-cycle-detection-908d1d9810}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-cycle-detection-908d1d9810-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/cycle-detection">有向图环检测</a>。</p><p>指向已经完成的节点并不构成当前路径上的环，这正是普通 visited 标记不够用的原因。</p><h3 id="entry-bipartite-graph-7ded796464" tabindex="-1">二分图判定 <a class="header-anchor" href="#entry-bipartite-graph-7ded796464" aria-label="Permalink to &quot;二分图判定 {#entry-bipartite-graph-7ded796464}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-bipartite-graph-7ded796464-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/bipartite-graph">二分图判定</a>。</p><p>二分图要求每条边的两端染成不同颜色；若相邻两点被迫同色，就不能二分。奇数长度环会造成这一冲突。</p><h2 id="scene-shortest-routes" tabindex="-1">按边权和查询范围求最短路 <a class="header-anchor" href="#scene-shortest-routes" aria-label="Permalink to &quot;按边权和查询范围求最短路 {#scene-shortest-routes}&quot;">​</a></h2><h3 id="entry-dijkstra-9ff28567bb" tabindex="-1">Dijkstra 最短路 <a class="header-anchor" href="#entry-dijkstra-9ff28567bb" aria-label="Permalink to &quot;Dijkstra 最短路 {#entry-dijkstra-9ff28567bb}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-dijkstra-9ff28567bb-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/dijkstra">Dijkstra 最短路</a>。</p><p>示例使用简单的 O(V²+E) 扫描；大型稀疏图可用堆降低选点成本。</p><h3 id="entry-bellman-ford-20dc270551" tabindex="-1">Bellman–Ford 最短路 <a class="header-anchor" href="#entry-bellman-ford-20dc270551" aria-label="Permalink to &quot;Bellman–Ford 最短路 {#entry-bellman-ford-20dc270551}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-bellman-ford-20dc270551-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/bellman-ford">Bellman–Ford 最短路</a>。</p><p>一轮松弛允许最短路径多经过一条边，因此最多 V−1 轮足以覆盖无环最短路径。再扫描一次若仍能改进，说明存在从起点可达的负权环。</p><p>算法允许负边，但时间 O(VE)，通常比 Dijkstra 慢。</p><h3 id="entry-floyd-warshall-3733afc1b1" tabindex="-1">Floyd–Warshall 最短路 <a class="header-anchor" href="#entry-floyd-warshall-3733afc1b1" aria-label="Permalink to &quot;Floyd–Warshall 最短路 {#entry-floyd-warshall-3733afc1b1}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-floyd-warshall-3733afc1b1-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/floyd-warshall">Floyd–Warshall 最短路</a>。</p><p>第 k 轮只允许前 k 个节点作为中转点，用 i→k→j 与现有 i→j 距离取较小值。三重循环得到所有点对的最短距离，适合顶点数较少且查询很多的图。 时间 O(V³)。</p><p>需要用足够大的 inf 表示不可达，并避免相加溢出。</p><h2 id="scene-connect-minimum-cost" tabindex="-1">用最低边权总和连接全部顶点 <a class="header-anchor" href="#scene-connect-minimum-cost" aria-label="Permalink to &quot;用最低边权总和连接全部顶点 {#scene-connect-minimum-cost}&quot;">​</a></h2><h3 id="entry-kruskal-24e59e257d" tabindex="-1">Kruskal 最小生成树 <a class="header-anchor" href="#entry-kruskal-24e59e257d" aria-label="Permalink to &quot;Kruskal 最小生成树 {#entry-kruskal-24e59e257d}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-kruskal-24e59e257d-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/kruskal">Kruskal 最小生成树</a>。</p><p>图不连通时无法得到单棵生成树，示例返回 −1。</p><h3 id="entry-prim-b7857a9f45" tabindex="-1">Prim 最小生成树 <a class="header-anchor" href="#entry-prim-b7857a9f45" aria-label="Permalink to &quot;Prim 最小生成树 {#entry-prim-b7857a9f45}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-prim-b7857a9f45-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/prim">Prim 最小生成树</a>。</p><p>本例 Prim 最小生成树使用 inf = int(^uint(0) &gt;&gt; 1) 作为本机 int 的最大值哨兵，避免固定 1&lt;&lt;60 在32位目标上不可表示。矩阵中的 -1 表示没有边；合法边权和总成本必须在 int 范围内且不与 inf 混淆。若当前最小候选仍为 inf，说明余下顶点不连通，返回 -1。</p><p>示例用方形对称矩阵与 O(V²) 扫描；-1 表示没有边，只接受非负边权，边权及总和须小于 int 上限。一般最小生成树可含负边，但本例用负数作哨兵，不能直接用于该情形。稀疏图通常用优先队列和邻接表。</p><h2 id="scene-respect-capacities" tabindex="-1">在容量限制下增加网络流量 <a class="header-anchor" href="#scene-respect-capacities" aria-label="Permalink to &quot;在容量限制下增加网络流量 {#scene-respect-capacities}&quot;">​</a></h2><h3 id="entry-max-flow-2108859bd0" tabindex="-1">最大流基础 <a class="header-anchor" href="#entry-max-flow-2108859bd0" aria-label="Permalink to &quot;最大流基础 {#entry-max-flow-2108859bd0}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-max-flow-2108859bd0-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/graphs/max-flow">最大流基础</a>。</p><p>残量网络记录一条边还能增加多少流，也记录沿反向边撤回已有流的能力。BFS 找到一条增广路后，取路上的最小剩余容量作为本次增量，并同步更新正反边。 本例使用 Edmonds–Karp 算法。</p><p>反复执行到找不到路径即得到最大流；示例会修改传入的容量矩阵。前提是方形非负容量矩阵、合法且不同的源点 s 和汇点 t，容量累加不超过 int；s == t 不属于本例契约，否则增广循环无法前进。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>预测两点有向环 0→1→0 的拓扑排序结果。再说明为何不能将 BFS 的首次到达套用于带权图。提示：先计算入度。</p><details class="details custom-block"><summary>参考解法</summary><p>两个入度都为 1，初始队列为空，返回空序列；数量小于 V 表示无完整拓扑序。带权路径可能经过更多边却总成本更低，应按边权前提选择最短路算法。</p></details>',79)])])}const m=e(i,[["render",s]]);export{f as __pageData,m as default};
